<?php
require_once __DIR__ . '/../includes/functions.php';require_admin();$pdo=db();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='toggle'){$id=(int)($_POST['room_id']??0);$q=$pdo->prepare("UPDATE rooms SET is_active=1-is_active WHERE id=?");$q->execute([$id]);redirect('/admin/rooms.php');}
 if($action==='add'){
  $name=trim($_POST['name']??'');$type=$_POST['room_type']??'private';$price=(float)($_POST['price_per_night']??0);$capacity=(int)($_POST['capacity']??1);$bed=trim($_POST['bed_info']??'');$description=trim($_POST['description']??'');$amenities=trim($_POST['amenities']??'');$image=trim($_POST['image_url']??'');
  if($name===''||$price<=0||$capacity<1||!in_array($type,['private','shared'],true)||!filter_var($image,FILTER_VALIDATE_URL))$error='Please provide a name, valid room type, positive price, capacity, and a valid image URL.';
  else{$q=$pdo->prepare("INSERT INTO rooms(name,room_type,price_per_night,capacity,bed_info,description,amenities,image_url,is_active,featured) VALUES(?,?,?,?,?,?,?,?,1,0)");$q->execute([$name,$type,$price,$capacity,$bed,$description,$amenities,$image]);redirect('/admin/rooms.php?added=1');}
 }
}
$rooms=$pdo->query("SELECT * FROM rooms ORDER BY id DESC")->fetchAll();$pageTitle='Manage rooms';include __DIR__ . '/../includes/header.php';
?>
