<?php if(isset($_GET['added'])): ?><div class="notice notice-success">Room added successfully.</div><?php endif; ?><?php if($error): ?><div class="notice notice-warning"><?= e($error) ?></div><?php endif; ?>
<div class="admin-room-layout"><div class="admin-table-wrap"><div class="table-heading"><h2>Room inventory</h2></div><div class="table-scroll"><table><thead><tr><th>Room</th><th>Type</th><th>Price</th><th>Capacity</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rooms as $r): ?><tr><td><strong><?= e($r['name']) ?></strong></td><td><?= e($r['room_type']) ?></td><td><?= money($r['price_per_night']) ?></td><td><?= (int)$r['capacity'] ?></td><td><?= $r['is_active']?'Active':'Hidden' ?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="room_id" value="<?= (int)$r['id'] ?>"><button class="small-button"><?= $r['is_active']?'Hide':'Activate' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="add-room-card"><p class="eyebrow">GROW YOUR COLLECTION</p><h2>Add a room</h2><form method="post" class="booking-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add"><label>Room name</label><input name="name" required><label>Room type</label><select name="room_type"><option value="private">Private</option><option value="shared">Shared</option></select><label>Price per night (₱)</label><input name="price_per_night" type="number" min="1" step="0.01" required><label>Guest capacity</label><input name="capacity" type="number" min="1" max="20" value="2" required><label>Bed information</label><input name="bed_info" placeholder="1 queen bed"><label>Description</label><textarea name="description" rows="3" required></textarea><label>Amenities (comma-separated)</label><input name="amenities" placeholder="Wi-Fi, Air conditioning"><label>Image URL (HTTPS)</label><input name="image_url" type="url" placeholder="https://..." required><button class="button button-dark full-width">Add room</button></form></div></div></section>
